import { useState, useEffect, useRef } from "react";

const BASE = "http://localhost:5000/api";

const api = async (path, options = {}) => {
  const token = localStorage.getItem("token");
  const headers = { "Content-Type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) };
  const res = await fetch(`${BASE}${path}`, { ...options, headers: { ...headers, ...options.headers } });
  return res.json();
};
const get = (p) => api(p);
const post = (p, b) => api(p, { method: "POST", body: JSON.stringify(b) });
const put = (p, b) => api(p, { method: "PUT", body: JSON.stringify(b) });
const del = (p) => api(p, { method: "DELETE" });

// ── Icons (inline SVG) ──────────────────────────────────────────────────────
const Icon = ({ name, cls = "w-5 h-5" }) => {
  const icons = {
    home: <path strokeLinecap="round" strokeLinejoin="round" d="M3 9.75L12 3l9 6.75V21H3V9.75z" />,
    predict: <path strokeLinecap="round" strokeLinejoin="round" d="M9.75 3.104a9 9 0 100 17.792M12 12l3-3m0 0l-3-3m3 3H9" />,
    drug: <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 12c0-4.142-3.358-7.5-7.5-7.5S4.5 7.858 4.5 12m15 0a7.5 7.5 0 11-15 0m6.75-1.5h3m-3 3h3" />,
    recommend: <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75m-3-7.036A11.959 11.959 0 013.598 6 11.99 11.99 0 003 9.749c0 5.592 3.824 10.29 9 11.623 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.571-.598-3.751h-.152c-3.196 0-6.1-1.248-8.25-3.285z" />,
    chat: <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 12a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H8.25m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H12m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0h-.375M21 12c0 4.556-4.03 8.25-9 8.25a9.764 9.764 0 01-2.555-.337A5.972 5.972 0 015.41 20.97a5.969 5.969 0 01-.474-.065 4.48 4.48 0 00.978-2.025c.09-.457-.133-.901-.467-1.226C3.93 16.178 3 14.189 3 12c0-4.556 4.03-8.25 9-8.25s9 3.694 9 8.25z" />,
    doctor: <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z" />,
    feedback: <path strokeLinecap="round" strokeLinejoin="round" d="M11.48 3.499a.562.562 0 011.04 0l2.125 5.111a.563.563 0 00.475.345l5.518.442c.499.04.701.663.321.988l-4.204 3.602a.563.563 0 00-.182.557l1.285 5.385a.562.562 0 01-.84.61l-4.725-2.885a.563.563 0 00-.586 0L6.982 20.54a.562.562 0 01-.84-.61l1.285-5.386a.562.562 0 00-.182-.557l-4.204-3.602a.563.563 0 01.321-.988l5.518-.442a.563.563 0 00.475-.345L11.48 3.5z" />,
    profile: <path strokeLinecap="round" strokeLinejoin="round" d="M17.982 18.725A7.488 7.488 0 0012 15.75a7.488 7.488 0 00-5.982 2.975m11.963 0a9 9 0 10-11.963 0m11.963 0A8.966 8.966 0 0112 21a8.966 8.966 0 01-5.982-2.275M15 9.75a3 3 0 11-6 0 3 3 0 016 0z" />,
    logout: <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 9V5.25A2.25 2.25 0 0013.5 3h-6a2.25 2.25 0 00-2.25 2.25v13.5A2.25 2.25 0 007.5 21h6a2.25 2.25 0 002.25-2.25V15m3 0l3-3m0 0l-3-3m3 3H9" />,
    dashboard: <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" />,
    users: <path strokeLinecap="round" strokeLinejoin="round" d="M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z" />,
    send: <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />,
    check: <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />,
  };
  return (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.8} stroke="currentColor" className={cls}>
      {icons[name]}
    </svg>
  );
};

// ── UI Helpers ──────────────────────────────────────────────────────────────
const Card = ({ children, cls = "" }) => <div className={`bg-white rounded-xl shadow-sm border border-gray-100 p-5 ${cls}`}>{children}</div>;
const Btn = ({ children, onClick, cls = "", type = "button", disabled = false }) => (
  <button type={type} onClick={onClick} disabled={disabled}
    className={`px-4 py-2 rounded-lg font-medium transition-all text-sm ${disabled ? "opacity-50 cursor-not-allowed" : ""} ${cls}`}>
    {children}
  </button>
);
const Input = ({ label, ...props }) => (
  <div>
    {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
    <input className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-400" {...props} />
  </div>
);
const Select = ({ label, options = [], ...props }) => (
  <div>
    {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
    <select className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-400" {...props}>
      <option value="">Select...</option>
      {options.map(o => <option key={o} value={o}>{o.replace(/_/g, ' ')}</option>)}
    </select>
  </div>
);
const Badge = ({ text, color = "green" }) => {
  const c = { green: "bg-green-100 text-green-700", yellow: "bg-yellow-100 text-yellow-700", red: "bg-red-100 text-red-700", blue: "bg-blue-100 text-blue-700", gray: "bg-gray-100 text-gray-600" };
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${c[color] || c.gray}`}>{text}</span>;
};
const Spinner = () => <div className="flex justify-center py-8"><div className="w-8 h-8 border-4 border-green-500 border-t-transparent rounded-full animate-spin" /></div>;
const Alert = ({ msg, type = "success" }) => {
  if (!msg) return null;
  const c = type === "error" ? "bg-red-50 text-red-700 border-red-200" : "bg-green-50 text-green-700 border-green-200";
  return <div className={`border rounded-lg px-4 py-2 text-sm mb-3 ${c}`}>{msg}</div>;
};

// ── Auth Pages ──────────────────────────────────────────────────────────────
function LoginPage({ onLogin, onSwitch }) {
  const [form, setForm] = useState({ email: "", password: "" });
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const submit = async (e) => {
    e.preventDefault(); setLoading(true); setErr("");
    const res = await post("/auth/login", form);
    setLoading(false);
    if (res.error) setErr(res.error);
    else onLogin(res.token, res.user);
  };
  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 flex items-center justify-center p-4">
      <Card cls="w-full max-w-md">
        <div className="text-center mb-6">
          <div className="w-14 h-14 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-3">
            <span className="text-2xl">🌿</span>
          </div>
          <h1 className="text-2xl font-bold text-gray-800">Ayurvedic Health</h1>
          <p className="text-gray-500 text-sm mt-1">Sign in to your account</p>
        </div>
        <Alert msg={err} type="error" />
        <form onSubmit={submit} className="space-y-4">
          <Input label="Email" type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} required />
          <Input label="Password" type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} required />
          <Btn type="submit" disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700">
            {loading ? "Signing in..." : "Sign In"}
          </Btn>
        </form>
        <p className="text-center text-sm text-gray-500 mt-4">
          No account? <button onClick={onSwitch} className="text-green-600 font-medium hover:underline">Register</button>
        </p>
        <div className="mt-4 p-3 bg-gray-50 rounded-lg text-xs text-gray-500">
          <strong>Demo:</strong> admin@ayurveda.com / admin123
        </div>
      </Card>
    </div>
  );
}

function RegisterPage({ onLogin, onSwitch }) {
  const [form, setForm] = useState({ name: "", email: "", password: "", age: "", gender: "Other" });
  const [err, setErr] = useState(""); const [loading, setLoading] = useState(false);
  const submit = async (e) => {
    e.preventDefault(); setLoading(true); setErr("");
    const res = await post("/auth/register", form);
    setLoading(false);
    if (res.error) setErr(res.error);
    else onLogin(res.token, res.user);
  };
  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 flex items-center justify-center p-4">
      <Card cls="w-full max-w-md">
        <div className="text-center mb-6">
          <div className="w-14 h-14 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-3"><span className="text-2xl">🌿</span></div>
          <h1 className="text-2xl font-bold text-gray-800">Create Account</h1>
        </div>
        <Alert msg={err} type="error" />
        <form onSubmit={submit} className="space-y-3">
          <Input label="Full Name" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required />
          <Input label="Email" type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} required />
          <Input label="Password" type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} required />
          <div className="grid grid-cols-2 gap-3">
            <Input label="Age" type="number" value={form.age} onChange={e => setForm({...form, age: e.target.value})} />
            <Select label="Gender" options={["Male","Female","Other"]} value={form.gender} onChange={e => setForm({...form, gender: e.target.value})} />
          </div>
          <Btn type="submit" disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700">
            {loading ? "Creating..." : "Create Account"}
          </Btn>
        </form>
        <p className="text-center text-sm text-gray-500 mt-4">Have an account? <button onClick={onSwitch} className="text-green-600 font-medium hover:underline">Sign In</button></p>
      </Card>
    </div>
  );
}

// ── Home Page ───────────────────────────────────────────────────────────────
function HomePage({ setPage, user }) {
  const features = [
    { icon: "🔬", title: "Disease Prediction", desc: "Predict diseases from symptoms using Naive Bayes ML", page: "predict", color: "bg-blue-50" },
    { icon: "💊", title: "Drug Recommendation", desc: "Get Ayurvedic medicine recommendations", page: "drug", color: "bg-green-50" },
    { icon: "📋", title: "Disease Recommendation", desc: "Top 3 probable diseases from your symptoms", page: "recommend", color: "bg-purple-50" },
    { icon: "🤖", title: "AI Health Assistant", desc: "Chat with AI for Ayurvedic guidance", page: "chat", color: "bg-yellow-50" },
    { icon: "👨‍⚕️", title: "Doctor Consultation", desc: "Book appointments and message doctors", page: "doctor", color: "bg-pink-50" },
    { icon: "⭐", title: "Feedback", desc: "Share your experience and suggestions", page: "feedback", color: "bg-orange-50" },
  ];
  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-green-600 to-emerald-600 rounded-2xl p-6 text-white">
        <h1 className="text-2xl font-bold mb-1">Welcome, {user?.name || "Guest"} 🌿</h1>
        <p className="text-green-100 text-sm">Your Ayurvedic Health Companion — Ancient Wisdom, Modern Technology</p>
        <div className="flex gap-3 mt-4">
          <Btn onClick={() => setPage("predict")} cls="bg-white text-green-700 hover:bg-green-50 text-xs">Predict Disease</Btn>
          <Btn onClick={() => setPage("drug")} cls="bg-green-700 text-white hover:bg-green-800 border border-green-500 text-xs">Get Medicine</Btn>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {features.map(f => (
          <button key={f.page} onClick={() => setPage(f.page)}
            className={`${f.color} rounded-xl p-5 text-left hover:shadow-md transition-all border border-transparent hover:border-green-200`}>
            <div className="text-2xl mb-2">{f.icon}</div>
            <h3 className="font-semibold text-gray-800 mb-1">{f.title}</h3>
            <p className="text-gray-500 text-xs">{f.desc}</p>
          </button>
        ))}
      </div>
      <Card>
        <h3 className="font-semibold text-gray-700 mb-3">About This System</h3>
        <p className="text-sm text-gray-500 leading-relaxed">
          This Ayurvedic Health Assistant combines traditional Ayurvedic medicine knowledge with modern machine learning 
          to provide personalized health recommendations. Using Naive Bayes classification trained on real datasets, 
          the system accurately predicts diseases and recommends appropriate Ayurvedic treatments.
        </p>
      </Card>
    </div>
  );
}

// ── Disease Prediction ──────────────────────────────────────────────────────
function PredictPage() {
  const [symptoms, setSymptoms] = useState([]);
  const [form, setForm] = useState({ symptom1: "", symptom2: "", symptom3: "" });
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");

  useEffect(() => { get("/symptoms").then(setSymptoms); }, []);

  const predict = async () => {
    if (!form.symptom1 || !form.symptom2 || !form.symptom3) { setErr("Please select all 3 symptoms"); return; }
    setLoading(true); setErr(""); setResult(null);
    const res = await post("/predict/disease", form);
    setLoading(false);
    if (res.error) setErr(res.error);
    else setResult(res);
  };

  return (
    <div className="space-y-5 max-w-2xl">
      <div>
        <h2 className="text-xl font-bold text-gray-800">Disease Prediction</h2>
        <p className="text-gray-500 text-sm mt-1">Select 3 symptoms to predict possible disease using Naive Bayes ML</p>
      </div>
      <Card>
        <Alert msg={err} type="error" />
        <div className="space-y-4">
          <Select label="Symptom 1" options={symptoms} value={form.symptom1} onChange={e => setForm({...form, symptom1: e.target.value})} />
          <Select label="Symptom 2" options={symptoms.filter(s => s !== form.symptom1)} value={form.symptom2} onChange={e => setForm({...form, symptom2: e.target.value})} />
          <Select label="Symptom 3" options={symptoms.filter(s => s !== form.symptom1 && s !== form.symptom2)} value={form.symptom3} onChange={e => setForm({...form, symptom3: e.target.value})} />
          <Btn onClick={predict} disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700">
            {loading ? "Predicting..." : "Predict Disease"}
          </Btn>
        </div>
      </Card>
      {result && (
        <Card>
          <h3 className="font-semibold text-gray-700 mb-4">Prediction Results</h3>
          <div className="bg-green-50 rounded-xl p-4 mb-4 text-center">
            <div className="text-3xl mb-1">🏥</div>
            <div className="text-xl font-bold text-green-800">{result.predicted}</div>
            <div className="text-sm text-green-600 mt-1">Confidence: <strong>{result.confidence}%</strong></div>
          </div>
          <div className="space-y-2">
            <p className="text-sm font-medium text-gray-600 mb-2">Top 3 Predictions:</p>
            {result.top3?.map((r, i) => (
              <div key={i} className="flex items-center gap-3">
                <div className="text-sm text-gray-600 w-4">{i+1}.</div>
                <div className="flex-1">
                  <div className="flex justify-between text-sm mb-1">
                    <span className="font-medium">{r.disease}</span>
                    <span className="text-gray-500">{r.confidence}%</span>
                  </div>
                  <div className="h-2 bg-gray-100 rounded-full"><div className="h-2 bg-green-500 rounded-full" style={{width: `${r.confidence}%`}} /></div>
                </div>
              </div>
            ))}
          </div>
          <p className="text-xs text-gray-400 mt-4">⚠️ This is for informational purposes only. Please consult a healthcare professional.</p>
        </Card>
      )}
    </div>
  );
}

// ── Drug Recommendation ─────────────────────────────────────────────────────
function DrugPage() {
  const [symptoms, setSymptoms] = useState([]);
  const [form, setForm] = useState({ symptom1: "", symptom2: "", symptom3: "", disease: "", age: "30", gender: "Any", severity: "Mild" });
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [predicted, setPredicted] = useState("");

  const diseases = ["Flu","Common Cold","COVID-19","Food Poisoning","Dengue","Pneumonia","Allergy","Gastritis","Typhoid","Malaria"];

  useEffect(() => {
    get("/symptoms").then(setSymptoms);
    get("/recommend/history").then(r => Array.isArray(r) && setHistory(r));
  }, []);

  const autoPredict = async () => {
    if (!form.symptom1 || !form.symptom2 || !form.symptom3) { setErr("Select 3 symptoms first"); return; }
    setLoading(true); setErr("");
    const res = await post("/predict/disease", { symptom1: form.symptom1, symptom2: form.symptom2, symptom3: form.symptom3 });
    setLoading(false);
    if (res.predicted) { setPredicted(res.predicted); setForm(f => ({...f, disease: res.predicted})); }
  };

  const recommend = async () => {
    if (!form.disease) { setErr("Please select or predict a disease"); return; }
    setLoading(true); setErr(""); setResult(null);
    const res = await post("/recommend/drug", { disease: form.disease, age: form.age, gender: form.gender, severity: form.severity });
    setLoading(false);
    if (res.error) setErr(res.error);
    else { setResult(res); get("/recommend/history").then(r => Array.isArray(r) && setHistory(r)); }
  };

  const statusColor = (s) => ({ Mild: "green", Moderate: "yellow", Severe: "red" }[s] || "gray");

  return (
    <div className="space-y-5 max-w-2xl">
      <div>
        <h2 className="text-xl font-bold text-gray-800">Drug Recommendation</h2>
        <p className="text-gray-500 text-sm mt-1">Get Ayurvedic medicine recommendations based on disease and symptoms</p>
      </div>
      <Card>
        <Alert msg={err} type="error" />
        <p className="text-sm font-medium text-gray-600 mb-3">Step 1: Select symptoms to auto-predict disease</p>
        <div className="grid grid-cols-3 gap-3 mb-3">
          <Select options={symptoms} value={form.symptom1} onChange={e => setForm({...form, symptom1: e.target.value})} label="Symptom 1" />
          <Select options={symptoms.filter(s => s !== form.symptom1)} value={form.symptom2} onChange={e => setForm({...form, symptom2: e.target.value})} label="Symptom 2" />
          <Select options={symptoms.filter(s => s !== form.symptom1 && s !== form.symptom2)} value={form.symptom3} onChange={e => setForm({...form, symptom3: e.target.value})} label="Symptom 3" />
        </div>
        <Btn onClick={autoPredict} disabled={loading} cls="bg-blue-600 text-white hover:bg-blue-700 mb-4 text-xs">🔬 Auto-Predict Disease</Btn>
        {predicted && <div className="bg-blue-50 rounded-lg p-2 mb-3 text-sm text-blue-700">Predicted: <strong>{predicted}</strong></div>}
        <hr className="my-4" />
        <p className="text-sm font-medium text-gray-600 mb-3">Step 2: Enter details for recommendation</p>
        <div className="grid grid-cols-2 gap-3">
          <Select label="Disease" options={diseases} value={form.disease} onChange={e => setForm({...form, disease: e.target.value})} />
          <Input label="Age" type="number" value={form.age} onChange={e => setForm({...form, age: e.target.value})} />
          <Select label="Gender" options={["Male","Female","Any"]} value={form.gender} onChange={e => setForm({...form, gender: e.target.value})} />
          <Select label="Severity" options={["Mild","Moderate","Severe"]} value={form.severity} onChange={e => setForm({...form, severity: e.target.value})} />
        </div>
        <Btn onClick={recommend} disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700 mt-4">
          {loading ? "Finding medicines..." : "💊 Get Recommendations"}
        </Btn>
      </Card>

      {result && result.recommendations?.length > 0 && (
        <Card>
          <h3 className="font-semibold text-gray-700 mb-4">Top Recommended Medicines for <span className="text-green-600">{result.disease}</span></h3>
          <div className="space-y-4">
            {result.recommendations.map((r, i) => (
              <div key={i} className="border border-green-100 rounded-xl p-4 bg-green-50">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <span className="text-xs text-green-600 font-medium">#{i+1} Recommended</span>
                    <h4 className="font-bold text-gray-800">{r.drug}</h4>
                  </div>
                  <div className="text-right">
                    <Badge text={r.severity} color={statusColor(r.severity)} />
                    <div className="text-xs text-gray-500 mt-1">Confidence: {r.confidence}%</div>
                  </div>
                </div>
                <div className="grid grid-cols-1 gap-2 text-sm">
                  <div><span className="font-medium text-gray-600">Dosage: </span><span className="text-gray-700">{r.dosage}</span></div>
