                <div className="mt-2 flex gap-2">
                  <input className="flex-1 border rounded px-2 py-1 text-xs" placeholder="Reply..." value={reply.userId===m.user_id?reply.msg:""} onChange={e=>setReply({userId:m.user_id,msg:e.target.value})} />
                  <Btn onClick={sendReply} cls="bg-green-600 text-white text-xs">Send</Btn>
                </div>
              )}
            </div>
          ))}
        </Card>
      )}

      {adminTab==="feedback" && (
        <Card>
          <h3 className="font-semibold mb-3">Feedback</h3>
          {feedback.map((f,i) => (
            <div key={i} className="border-b py-3">
              <div className="flex justify-between text-sm"><span className="font-medium">{f.user_name}</span><Badge text={f.type} /></div>
              <p className="text-gray-700 text-sm mt-1">{f.message}</p>
              <div className="text-yellow-400 text-xs mt-1">{"★".repeat(f.rating||0)}</div>
            </div>
          ))}
        </Card>
      )}

      {adminTab==="drugs" && (
        <Card>
          <h3 className="font-semibold mb-3">Drug Database ({drugs.length} records)</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead><tr className="text-left text-gray-500 border-b">{["Disease","Drug","Dosage","Severity","Precautions"].map(h=><th key={h} className="py-2 pr-3">{h}</th>)}</tr></thead>
              <tbody>
                {drugs.map((d,i) => (
                  <tr key={i} className="border-b border-gray-50 hover:bg-gray-50">
                    <td className="py-2 pr-3 font-medium">{d.disease}</td>
                    <td className="py-2 pr-3 text-green-700">{d.drug}</td>
                    <td className="py-2 pr-3 text-gray-600">{d.dosage}</td>
                    <td className="py-2 pr-3"><Badge text={d.severity} color={{Mild:"green",Moderate:"yellow",Severe:"red"}[d.severity]||"gray"} /></td>
                    <td className="py-2 pr-3 text-gray-500">{d.precautions}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {adminTab==="diseases" && (
        <Card>
          <h3 className="font-semibold mb-3">Disease Dataset ({diseases.length} records)</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead><tr className="text-left text-gray-500 border-b">{["Disease","Symptom 1","Symptom 2","Symptom 3"].map(h=><th key={h} className="py-2 pr-4">{h}</th>)}</tr></thead>
              <tbody>
                {diseases.map((d,i) => (
                  <tr key={i} className="border-b border-gray-50 hover:bg-gray-50">
                    <td className="py-2 pr-4 font-medium">{d.disease}</td>
                    <td className="py-2 pr-4 text-gray-600">{d.symptom1?.replace(/_/g," ")}</td>
                    <td className="py-2 pr-4 text-gray-600">{d.symptom2?.replace(/_/g," ")}</td>
                    <td className="py-2 pr-4 text-gray-600">{d.symptom3?.replace(/_/g," ")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}

// ── Sidebar Nav ─────────────────────────────────────────────────────────────
function Sidebar({ page, setPage, user, logout }) {
  const navItems = [
    { id: "home", label: "Home", icon: "home" },
    { id: "predict", label: "Disease Prediction", icon: "predict" },
    { id: "drug", label: "Drug Recommendation", icon: "drug" },
    { id: "recommend", label: "Disease Recommend", icon: "recommend" },
    { id: "chat", label: "AI Assistant", icon: "chat" },
    { id: "doctor", label: "Doctor Consult", icon: "doctor" },
    { id: "feedback", label: "Feedback", icon: "feedback" },
    { id: "profile", label: "Profile", icon: "profile" },
  ];
  if (user?.role === "admin" || user?.role === "doctor") {
    navItems.push({ id: "admin", label: "Admin Panel", icon: "dashboard" });
  }
  return (
    <aside className="w-56 bg-white border-r border-gray-100 flex flex-col min-h-screen">
      <div className="p-4 border-b border-gray-100">
        <div className="flex items-center gap-2">
          <span className="text-2xl">🌿</span>
          <div><div className="font-bold text-gray-800 text-sm leading-tight">Ayurvedic</div><div className="text-xs text-gray-500">Health Assistant</div></div>
        </div>
      </div>
      <nav className="flex-1 p-3 space-y-1">
        {navItems.map(n => (
          <button key={n.id} onClick={() => setPage(n.id)}
            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${page===n.id?"bg-green-600 text-white":"text-gray-600 hover:bg-gray-50"}`}>
            <Icon name={n.icon} cls="w-4 h-4 flex-shrink-0" />
            <span className="truncate">{n.label}</span>
          </button>
        ))}
      </nav>
      <div className="p-3 border-t border-gray-100">
        <div className="px-3 py-2 mb-1">
          <div className="text-sm font-medium text-gray-700 truncate">{user?.name}</div>
          <div className="text-xs text-gray-400 truncate">{user?.email}</div>
        </div>
        <button onClick={logout} className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm text-red-500 hover:bg-red-50">
          <Icon name="logout" cls="w-4 h-4" /> Logout
        </button>
      </div>
    </aside>
  );
}

// ── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [user, setUser] = useState(() => { try { return JSON.parse(localStorage.getItem("user")); } catch { return null; } });
  const [token, setToken] = useState(() => localStorage.getItem("token"));
  const [authView, setAuthView] = useState("login");
  const [page, setPage] = useState("home");

  const handleLogin = (t, u) => { localStorage.setItem("token", t); localStorage.setItem("user", JSON.stringify(u)); setToken(t); setUser(u); };
  const handleLogout = () => { localStorage.clear(); setToken(null); setUser(null); setPage("home"); };

  if (!token || !user) {
    return authView==="login"
      ? <LoginPage onLogin={handleLogin} onSwitch={() => setAuthView("register")} />
      : <RegisterPage onLogin={handleLogin} onSwitch={() => setAuthView("login")} />;
  }

  const renderPage = () => {
    if (page === "admin" && (user.role === "admin" || user.role === "doctor"))
      return <AdminDashboard user={user} logout={handleLogout} setPage={setPage} />;
    switch(page) {
      case "home": return <HomePage setPage={setPage} user={user} />;
      case "predict": return <PredictPage />;
      case "drug": return <DrugPage />;
      case "recommend": return <RecommendPage />;
      case "chat": return <ChatPage />;
      case "doctor": return <DoctorPage user={user} />;
      case "feedback": return <FeedbackPage />;
      case "profile": return <ProfilePage user={user} logout={handleLogout} />;
      default: return <HomePage setPage={setPage} user={user} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <Sidebar page={page} setPage={setPage} user={user} logout={handleLogout} />
      <main className="flex-1 p-6 overflow-y-auto">{renderPage()}</main>
    </div>
  );
}
